function shadeHexColor(hex, factor) {
    const value = hex.replace('#', '');

    if (!/^[0-9a-fA-F]{6}$/.test(value)) {
        return hex;
    }

    const channels = [0, 2, 4].map(index =>
        parseInt(value.slice(index, index + 2), 16)
    );

    return '#' + channels
        .map(channel =>
            Math.round(channel * factor)
                .toString(16)
                .padStart(2, '0')
        )
        .join('');
}
